using BenchmarkDotNet.Running;
using TextAnalysis;

BenchmarkSwitcher.FromAssembly(typeof(TextAnalyzerBenchmarks).Assembly).Run(args);

[MemoryDiagnoser]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    private static readonly string SampleText =
        "The quick brown fox jumps over the lazy dog " +
        "A stitch in time saves nine and every cloud has a silver lining " +
        "To be or not to be that is the question whether it is nobler " +
        "in the mind to suffer the slings and arrows of outrageous fortune " +
        "or to take arms against a sea of troubles and by opposing end them " +
        "All that glitters is not gold and not all who wander are lost " +
        "The only thing we have to fear is fear itself so let us begin " +
        "Ask not what your country can do for you ask what you can do for your country";

    [GlobalSetup]
    public void Setup() => _analyzer = new TextAnalyzer(SampleText);

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

